package com.pollhub.service;
import com.pollhub.dto.PollRequest;import com.pollhub.entity.*;import com.pollhub.repository.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.security.access.AccessDeniedException;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class PollServiceTest{@Mock PollRepository polls;@Mock CategoryRepository categories;@Mock UserRepository users;@Mock VoteRepository votes;@InjectMocks PollService service;User owner;Category category;
 @BeforeEach void setup(){owner=new User();owner.setId(1L);owner.setEmail("owner@test.rs");owner.setFirstName("A");owner.setLastName("B");category=new Category();category.setId(2L);category.setName("Sport");}
 @Test void createsPoll(){when(users.findByEmail(owner.getEmail())).thenReturn(Optional.of(owner));when(categories.findById(2L)).thenReturn(Optional.of(category));when(polls.save(any())).thenAnswer(i->{Poll p=i.getArgument(0);p.setId(3L);p.getOptions().forEach(o->o.setId((long)p.getOptions().indexOf(o)+1));return p;});when(votes.countByPollId(3L)).thenReturn(0L);var r=service.create(new PollRequest("Naslov","Opis",2L,List.of("Da","Ne"),LocalDateTime.now().plusDays(1)),owner.getEmail());assertEquals(2,r.options().size());assertTrue(r.active());}
 @Test void preventsModificationByAnotherUser(){Poll p=new Poll();p.setId(1L);p.setCreator(owner);when(polls.findById(1L)).thenReturn(Optional.of(p));assertThrows(AccessDeniedException.class,()->service.close(1L,"other@test.rs"));}
}
